def transform(grid):
    h, w = len(grid), len(grid[0])

    # A solid separator divides the source pattern from its erasing mask.
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            top = grid[:r]
            mask = grid[r + 1:]
            return [
                [2 if top[i][j] != 0 and mask[i][j] != 0 else 0
                 for j in range(len(top[0]))]
                for i in range(len(top))
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            mask = [row[c + 1:] for row in grid]
            return [
                [2 if left[i][j] != 0 and mask[i][j] != 0 else 0
                 for j in range(c)]
                for i in range(h)
            ]

    return grid
